"Apoya el antebrazo en el banco con la palma arriba.": [
"Rest your forearm on the bench, palm up.",
"Pose l’avant-bras sur le banc, paume vers le haut.",
"ركّز دراعك على البانك، الكف للفوق."
],
"Apoya el muslo en la almohadilla y el rodillo detrás del tobillo.": [
"Rest your thigh on the pad and the roller behind your ankle.",
"Pose la cuisse sur le coussin et le rouleau derrière la cheville.",
"حط فخدك على الكوسان والرولو مور الكعبة."
],
"Apoya el pecho en el soporte y coge las asas con los brazos estirados.": [
"Rest your chest on the pad and grab the handles with straight arms.",
"Pose la poitrine sur l’appui et saisis les poignées bras tendus.",
"ركّز صدرك على الكوسان وشد البوانيي بدراعاتك ممدودين."
],
"Apoya el pecho en el soporte.": [
"Rest your chest on the pad.",
"Pose la poitrine sur l’appui.",
"ركّز صدرك على الكوسان."
],
"Apoya la espalda en el respaldo y coloca el cinturón o la almohadilla sobre la cadera.": [
"Rest your back on the backrest and place the belt or pad over your hips.",
"Appuie le dos contre le dossier et place la ceinture ou le coussin sur les hanches.",
"ركّز ضهرك على الضهرية وحط الحزام ولا الكوسان فوق الورك."
],
"Apoya la parte de atrás de los brazos en el banco Scott.": [
"Rest the back of your arms on the preacher bench.",
"Pose l’arrière des bras sur le pupitre (banc Larry Scott).",
"ركّز اللور ديال دراعاتك على بانك البريشر."
],
"Apoya las rodillas en la plataforma.": [
"Rest your knees on the platform.",
"Pose les genoux sur la plateforme.",
"ركّز ركابيك على البلاتفورم."
],
"Apoya los brazos en el soporte.": [
"Rest your arms on the pad.",
"Pose les bras sur l’appui.",
"ركّز دراعاتك على الكوسان."
],
"Apoya rodilla y mano del mismo lado en el banco.": [
"Put the knee and hand of the same side on the bench.",
"Pose le genou et la main du même côté sur le banc.",
"حط الركبة واليد من نفس الجيهة على البانك."
],
"Apoya una mano y una rodilla en el banco.": [
"Put one hand and one knee on the bench.",
"Pose une main et un genou sur le banc.",
"حط يد وحدة وركبة وحدة على البانك."
],
"Apoyar el peso en la pierna de atrás.": [
"Putting your weight on the back leg.",
"Mettre le poids sur la jambe arrière.",
"تحط الوزن على الرجل اللورانية."
],
"Apoyo justo por debajo de la cadera.": [
"Pad just below your hips.",
"Appui juste sous les hanches.",
"كوسان شوية تحت الورك."
],
"Aprende la técnica con poco peso; es el ejercicio con más carga de la biblioteca.": [
"Learn the technique with light weight; it’s the heaviest exercise in the library.",
"Apprends la technique avec peu de poids : c’est l’exercice le plus lourd de la bibliothèque.",
"تعلّم التقنية بوزن خفيف؛ هادا أثقل تمرين ف المكتبة."
],
"Aprieta arriba un segundo.": [
"Squeeze for a second at the top.",
"Contracte une seconde en haut.",
"زيّر ثانية ف الفوق."
],
"Aprieta el abdomen durante todo el movimiento.": [
"Brace your abs throughout the movement.",
"Gaine les abdos pendant tout le mouvement.",
"زيّر البطن ف الحركة كاملة."
],
"Aprieta glúteos y abdomen.": [
"Squeeze your glutes and abs.",
"Serre les fessiers et les abdos.",
"زيّر الأرداف والبطن."
],
"Aprieta los glúteos arriba un segundo.": [
"Squeeze your glutes for a second at the top.",
"Serre les fessiers une seconde en haut.",
"زيّر الأرداف ثانية ف الفوق."
],
"Aprieta los glúteos arriba.": [
"Squeeze your glutes at the top.",
"Serre les fessiers en haut.",
"زيّر الأرداف ف الفوق."
],
"Apunta el número de la placa o los discos que cargues. Cada máquina es distinta: compárate siempre en la misma.": [
"Log the number on the stack or the plates you load. Every machine is different: always compare yourself on the same one.",
"Note le chiffre de la plaque ou les disques que tu charges. Chaque machine est différente : compare-toi toujours sur la même.",
"سجّل الرقم اللي ف البيل ولا الديسكات اللي كتحط. كل ماشينة كتختلف: ديما قارن راسك على نفس الماشينة."
],
"Apunta el número que marca la placa donde metes el pasador. Cada máquina es distinta: compárate siempre en la misma.": [
"Log the number on the plate where you put the pin. Every machine is different: always compare yourself on the same one.",
"Note le chiffre de la plaque où tu mets la goupille. Chaque machine est différente : compare-toi toujours sur la même.",
"سجّل الرقم ديال الديسك فين حطيتي الگوبيي. كل ماشينة كتختلف: ديما قارن راسك على نفس الماشينة."
],
"Apunta el peso de una sola mancuerna. Si coges dos de {n} kg, escribe {n}, no {n}.": [
"Log the weight of one dumbbell. If you pick up two {n} kg ones, write {n}, not {n}.",
"Note le poids d’un seul haltère. Si tu prends deux haltères de {n} kg, écris {n}, pas {n}.",
"سجّل الوزن ديال هالتير وحدة. إلا خديتي جوج ديال {n} كيلو، كتب {n}، ماشي {n}."
],
"Apunta el total: la barra más todos los discos. Ejemplo: barra de {n} kg + un disco de {n} a cada lado = {n} kg.": [
"Log the total: the bar plus all the plates. Example: {n} kg bar + one {n} kg plate on each side = {n} kg.",
"Note le total : la barre plus tous les disques. Exemple : barre de {n} kg + un disque de {n} de chaque côté = {n} kg.",
"سجّل المجموع: البارا وجميع الديسكات. مثال: بارا ديال {n} كيلو + ديسك ديال {n} كيلو ف كل جيهة = {n} كيلو."
],
"Apunta los kilos de AYUDA que marques en la máquina. Cuanta menos ayuda pongas, más fuerte eres: el objetivo es ir bajándola.": [
"Log the kilos of ASSISTANCE you set on the machine. The less assistance, the stronger you are: the goal is to keep lowering it.",
"Note les kilos d’AIDE réglés sur la machine. Moins tu as d’aide, plus tu es fort : l’objectif est de la réduire peu à peu.",
"سجّل الكيلوات ديال المساعدة اللي حطيتي ف الماشينة. كل ما قلّات المساعدة، كل ما كنتي قوي: الهدف هو تبقى تنقصها."
],
"Apunta tus medidas una vez al mes para ver cómo crecen.": [
"Log your measurements once a month to see them grow.",
"Note tes mensurations une fois par mois pour les voir progresser.",
"سجّل القياسات ديالك مرة ف الشهر باش تشوفهم كيكبرو."
],
"Archivo cargado. Pulsa «Importar» para restaurar.": [
"File loaded. Tap “Import” to restore.",
"Fichier chargé. Appuie sur « Importer » pour restaurer.",
"الفيشي تحمّل. ورّك على “Importer” باش ترجّع الداتا."
],
